import re, sys, json
path = sys.argv[1]
steps = {}
val_steps = {}
pat = re.compile(r'step:(\d+) - (.*)$')
with open(path, errors='replace') as f:
    for line in f:
        m = pat.search(line)
        if not m: continue
        step = int(m.group(1))
        kv = {}
        for item in m.group(2).split(' - '):
            if ':' not in item: continue
            k, v = item.rsplit(':', 1)
            try: kv[k.strip()] = float(v)
            except: kv[k.strip()] = v.strip()
        if any(k.startswith('val') for k in kv):
            val_steps.setdefault(step, {}).update(kv)
        else:
            steps.setdefault(step, {}).update(kv)
json.dump({'train': steps, 'val': val_steps}, open('/tmp/analysis/metrics.json','w'))
print("train steps:", len(steps), "min/max:", min(steps) if steps else None, max(steps) if steps else None)
print("val steps:", sorted(val_steps))
print()
print("=== VALIDATION ===")
for s in sorted(val_steps):
    d = val_steps[s]
    print(s, {k: round(v,4) if isinstance(v,float) else v for k,v in d.items()})
