def _safe_bool(value):
    """Coerce a comparison result (possibly numpy array/bool_) to a Python bool."""
    try:
        if isinstance(value, np.ndarray):
            return bool(value.all()) if value.size else False
        return bool(value)
    except Exception:
        return False

def _call_based_match(output, expected):
    """TACO/APPS call-based comparison: ``expected`` is normally ``[return_value]``."""
    if isinstance(output, tuple):
        output = list(output)
    tmp_result = _safe_bool(output == expected)
    if not tmp_result and isinstance(expected, list) and expected:
        tmp_result = _safe_bool(output == expected[0])
    if not tmp_result:
        # ground truth sequences are lists, never tuples
        try:
            if isinstance(output, list) and output and isinstance(output[0], tuple):
                as_lists = [list(x) for x in output]
                tmp_result = _safe_bool(as_lists == expected) or (
                    isinstance(expected, list) and bool(expected) and _safe_bool(as_lists == expected[0])
                )
        except Exception:
            pass
    return tmp_result

def run_test(sample, test=None, debug=False, fail_debug=None, stop_on_fail=False):
    """Run ``test`` (generated code) against ``sample['input_output']``.

    Mirrors the TACO/APPS ``testing_util.run_test`` harness:
      * ``fn_name`` present  -> call-based: call ``fn(*inputs)`` (or
        ``Solution().fn(*inputs)``) and compare the return value;
      * ``fn_name`` absent   -> standard-input: feed ``inputs`` on stdin and
