class Capturing(list):

    def __enter__(self):
        self._stdout = sys.stdout
        sys.stdout = self._stringio = StringIO()

        self._stringio.close = lambda x: 1
        return self

    def __exit__(self, *args):
        self.extend(self._stringio.getvalue().splitlines())
        del self._stringio
        sys.stdout = self._stdout

def _safe_bool(value):
    """Coerce a comparison result (possibly numpy array/bool_) to a Python bool."""
    try:
        if isinstance(value, np.ndarray):
            return bool(value.all()) if value.size else False
        return bool(value)
    except Exception:
        return False

def _call_based_match(output, expected):
    """TACO/APPS call-based comparison: ``expected`` is normally ``[return_value]``."""
    if isinstance(output, tuple):
        output = list(output)
    tmp_result = _safe_bool(output == expected)
    if not tmp_result and isinstance(expected, list) and expected:
        tmp_result = _safe_bool(output == expected[0])
    if not tmp_result:
        # ground truth sequences are lists, never tuples
        try:
            if isinstance(output, list) and output and isinstance(output[0], tuple):
                as_lists = [list(x) for x in output]
                tmp_result = _safe_bool(as_lists == expected) or (
                    isinstance(expected, list) and bool(expected) and _safe_bool(as_lists == expected[0])
                )
        except Exception:
            pass
    return tmp_result

def run_test(sample, test=None, debug=False, fail_debug=None, stop_on_fail=False):
    """Run ``test`` (generated code) against ``sample['input_output']``.

    Mirrors the TACO/APPS ``testing_util.run_test`` harness:
      * ``fn_name`` present  -> call-based: call ``fn(*inputs)`` (or
        ``Solution().fn(*inputs)``) and compare the return value;
      * ``fn_name`` absent   -> standard-input: feed ``inputs`` on stdin and
        compare captured stdout.
    Returns a list with one entry per executed test case: ``True`` (pass),
    ``False`` (wrong answer), ``-1`` (runtime error / timeout), ``-2``
    (compilation error).  With ``stop_on_fail=True`` the loop ends at the
    first non-passing case.
    """

    reliability_guard()
    _install_sigalrm()

    if debug:
        print(f'start = {datetime.now().time()}')

    try:
        in_outs = json.loads(sample['input_output'])
    except ValueError:
        in_outs = None
    which_type = CODE_TYPE.standard_input
    method_name = None
    if in_outs:
        fn_name = in_outs.get('fn_name')
        if isinstance(fn_name, str):
            fn_name = fn_name.strip()
        if fn_name:
            which_type = CODE_TYPE.call_based
            method_name = fn_name
        else:
            which_type = CODE_TYPE.standard_input
            method_name = None

    if debug:
        print(f'loaded input_output = {datetime.now().time()}')

    if test is None:
        return in_outs
    elif test is not None:
        ctx = {"index": None, "inputs": None, "expected": None, "output": None, "error": None}
        results = _ResultList(fail_debug, ctx)
        if not in_outs or not in_outs.get('inputs'):
            ctx["error"] = "no test cases in ground truth"
            results.append(-2)
            return results
        sol = 'import sys\nimport time\nimport itertools\nfrom itertools import accumulate, product, permutations, combinations\nimport collections\nfrom collections import Counter, OrderedDict, deque, defaultdict, ChainMap\nfrom functools import lru_cache\nimport math\nfrom math import sqrt, sin, cos, tan, ceil, fabs, floor, gcd, exp, log, log2\nimport fractions\nfrom typing import List, Tuple\nimport numpy as np\nimport random\nimport heapq\nfrom heapq import *\n'
        if debug:
            print(f'loading test code = {datetime.now().time()}')

        if which_type == CODE_TYPE.call_based:
            # Call-based: the generated code defines `fn_name` (optionally inside
            # `class Solution`); import it as a module and fetch the function.
            sol += test
            if debug:
                print(f'sol = {sol}')
            signal.alarm(timeout)
            try:
                with Capturing():
                    tmp_sol = _runtime_module().from_string('tmp_sol', '', sol)
                    if 'class Solution' not in test:
                        tmp = tmp_sol
                    else:
                        tmp = tmp_sol.Solution()
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if debug:
                    print(f'type 0 compilation error = {e}')
                ctx["error"] = f"compile: {e!r}"
                results.append(-2)
                return results
            signal.alarm(0)

        elif which_type == CODE_TYPE.standard_input:

            tmp_test = test.split('\n')

            new_test = []
            for x in tmp_test:
                if (not x.startswith('from ')) and (
                        not x.startswith('import ')):
                    new_test.append('\t' + x + '\n')
                else:
                    new_test.append(x + '\n')
            tmp_test = new_test

            new_test = ''
            started = False
            for i in tmp_test:
                if i.startswith('\t') and not started:
                    new_test += 'stdin = sys.stdin\nstdout = sys.stdout\n'
                    new_test += 'def code():\n'
                    new_test += i
                    started = True
                elif started and ((i.startswith('from ')) or
                                  (i.startswith('import '))):
                    new_test += '\t' + i
                else:
                    new_test += i
            tmp_test = new_test

            sol += tmp_test
            if debug:
                print(f'sol = {sol}')
            method_name = 'code'
            signal.alarm(timeout)
            try:
                tmp_sol = _runtime_module().from_string('tmp_sol', '', sol)
                tmp = tmp_sol
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if debug:
                    print(f'type 1 compilation error = {e}')
                ctx["error"] = f"compile: {e!r}"
                results.append(-2)
                return results
            signal.alarm(0)
        if debug:
            print(f'get method = {datetime.now().time()}')

        try:
            method = getattr(tmp,
                             method_name)
        except:
            signal.alarm(0)
            e = sys.exc_info()
            print(f'unable to get function error = {e}')
            ctx["error"] = f"getattr: {e!r}"
            results.append(-2)
            return results

        for index, inputs in enumerate(in_outs['inputs']):
