except:
    True

if debug:
    print(
        f'time: {datetime.now().time()} testing index = {index}  inputs = {inputs}, {type(inputs)}. type = {which_type}'
    )
if which_type == CODE_TYPE.call_based:
    faulthandler.enable()
    signal.alarm(timeout)
    try:
        with Capturing():
            if isinstance(inputs, list):
                output = method(*inputs)
            else:
                output = method(inputs)
        signal.alarm(0)
        if isinstance(output, tuple):
            output = list(output)
        ctx["output"] = _clip_debug(output)
        tmp_result = _call_based_match(output, in_outs['outputs'][index])
        if debug:
            print(
                f"outputs = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {tmp_result}"
            )
        results.append(tmp_result)
    except Exception as e:
        signal.alarm(0)
        if debug:
            print(f'Call-based runtime error or time limit exceeded error = {repr(e)}{e}')
        ctx["error"] = f"runtime: {e!r}"
        results.append(-1)
    finally:
        signal.alarm(0)
        faulthandler.disable()
    continue

if which_type == CODE_TYPE.standard_input:
    faulthandler.enable()
    signal.alarm(timeout)
    passed = False

    if isinstance(inputs, list):
        inputs = '\n'.join(str(x) for x in inputs)
    if isinstance(in_outs['outputs'][index], list):
        in_outs['outputs'][index] = '\n'.join(
            str(x) for x in in_outs['outputs'][index])

    with Capturing() as output:
        try:
            call_method(method, inputs)

            signal.alarm(0)
            passed = True
        except Exception as e:

            signal.alarm(0)
            print(
                f'Call-based runtime error or time limit exceeded error = {repr(e)}{e}'
            )
            ctx["error"] = f"runtime: {e!r}"
            results.append(-1)
        signal.alarm(0)
    ctx["output"] = list(output)

    if not passed:
        if debug:
            nl = '\n'
            if not isinstance(inputs, list):
                print(
                    f"not passed output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs.replace(nl,' new-line ')}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                )
            else:
                print(
                    f"not passed output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                )
        continue

    if passed and debug:
        print(
            f"==> output = {output}, test outputs = {in_outs['outputs'][index]}"

def _run_all_tests(solution_str, ground_truth, extra_info=None, stop_on_fail=False):
    """Run the generated program against every test case of ``ground_truth``.

    ``stop_on_fail=True`` stops at the first non-passing test case.  The binary
    (all-tests-pass) verdict is identical either way; only the auxiliary
    ``pass_rate`` becomes a lower bound.  It bounds the wall-clock cost of
    hanging/slow generations (otherwise every test case burns its own 4 s alarm
    until the global timeout).
    """

    extra_info = extra_info or {}
    code = post_process(solution_str)
    in_outs = _parse_ground_truth(ground_truth)
    sample = {"input_output": json.dumps(in_outs)}
    n_cases = len(in_outs.get("inputs") or [])
    timeout = min(max(TIMEOUT, 4 * max(n_cases, 1) + 1), 120)
    raw, fail_debug = check_correctness(
        sample, code, timeout=timeout, debug=False, stop_on_fail=stop_on_fail
    )
    results = _to_bool_results(raw)
    n_pass = sum(1 for r in results if r is True)
    if fail_debug is None:
        fail_debug = {}
    if any(r is not True for r in results) and not fail_debug:
        fail_idx = next((i for i, r in enumerate(results) if r is not True), 0)
        fail_debug = {
            "result": results[fail_idx] if results else -1,
            "fail_index": fail_idx,
            "error": "no_per_case_debug",
        }
    if fail_debug:
        fail_debug.setdefault("code", _clip_debug(code, 1200))
        fail_debug.setdefault("n_tests", n_cases)
        fail_debug.setdefault("n_pass", n_pass)
        if isinstance(extra_info, dict):
            fail_debug.setdefault("problem_id", extra_info.get("problem_id"))
            fail_debug.setdefault("code_type", extra_info.get("code_type"))
            fail_debug.setdefault("fn_name", extra_info.get("fn_name") or in_outs.get("fn_name"))
        return results, fail_debug
    return results, None

def _summarize(results):
    n = len(results) if results else 0
    if n == 0:
        return 0.0, 0.0
    n_pass = sum(1 for r in results if r is True)
    pass_rate = n_pass / n
    binary = 1.0 if n_pass == n else 0.0
    return float(pass_rate), float(binary)

def compute_score_pass_rate(solution_str, ground_truth, extra_info=None, **kwargs):

    results, _ = _run_all_tests(solution_str, ground_truth, extra_info, stop_on_fail=False)
    pass_rate, _ = _summarize(results)
    return pass_rate

def compute_score_binary(solution_str, ground_truth, extra_info=None, **kwargs):

    results, _ = _run_all_tests(solution_str, ground_truth, extra_info, stop_on_fail=True)
    _, binary = _summarize(results)
    return binary

def _is_validate(extra_info):
    if not isinstance(extra_info, dict):
        return False
    if extra_info.get("validate"):
        return True
    return extra_info.get("split") == "test"

def compute_score(solution_str=None, ground_truth=None, extra_info=None, data_source=None, **kwargs):
    """Binary TACO reward: 1.0 iff the generated program passes every test case.

    Test execution stops at the first failing case (the binary verdict cannot
    change afterwards), so ``pass_rate`` is a lower bound on the true pass rate
    for failing generations and exact (1.0) for passing ones.
    """

    if solution_str is None:
        solution_str = kwargs.get("completion") or kwargs.get("generation") or ""
    results, fail_debug = _run_all_tests(solution_str, ground_truth, extra_info, stop_on_fail=True)
    pass_rate, binary = _summarize(results)
    score = binary
    return {
        "score": float(score),
        "acc": float(binary),
        "pass_rate": float(pass_rate),
        "fail_debug": fail_debug,
    }

